import torch

def run(a, x):
    return torch.special.gammainc(a, x)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    result = {}
    for name in ("a", "x"):
        result[name] = torch.rand(
            ctx[f"{name}__shape"],
            dtype=_dtype_from_context(ctx, name),
            device=device,
        ) * 10.0 + 0.1
    return result
